class Solution {
    public boolean checkGoodInteger(int n) {
        String s = Integer.toString(n);
        long ds = 0, ss = 0;
        for (char c : s.toCharArray()) {
            int d = c - '0';
            ds += d;
            ss += (long) d * d;
        }
        return ss - ds >= 50;
    }
}

